import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long k = sc.nextLong();
        String s = sc.next();

        int[] count = new int[26];
        int l = 0, best = 0;
        for (int rr = 0; rr < s.length(); rr++) {
            count[s.charAt(rr) - 'A']++;
            int most = 0;
            for (int c : count) most = Math.max(most, c);
            while ((rr - l + 1) - most > k) {
                count[s.charAt(l) - 'A']--;
                l++;
                most = 0;
                for (int c : count) most = Math.max(most, c);
            }
            best = Math.max(best, rr - l + 1);
        }
        System.out.println(best);
    }
}
